use super::*;
#[derive(Default)] pub(super) struct GameplayUi {pub paint:bool,pub erase:bool,pub solid:bool,pub layer:i32,pub asset:String,pub link:Option<usize>,pub positions:HashMap<(Uuid,usize),egui::Vec2>,pub atlas:[u32;3],pub auto:bool}
pub(super) fn material(ui:&mut egui::Ui,o:&mut Object,uk:bool){ui.collapsing(tr(uk,"Фізичні параметри","Physics material"),|ui|{ui.add(egui::DragValue::new(&mut o.material.gravity_scale).range(0. ..=10.).prefix("Gravity × "));ui.add(egui::DragValue::new(&mut o.material.speed).range(0. ..=2000.).prefix("Speed "));ui.add(egui::DragValue::new(&mut o.material.jump_speed).range(0. ..=2000.).prefix("Jump "));ui.add(egui::Slider::new(&mut o.material.restitution,0. ..=1.).text("Bounce"));});}
pub(super) fn tiles(ui:&mut egui::Ui,e:&mut Editor){let uk=e.uk;let g=&mut e.gameplay;ui.horizontal_wrapped(|ui|{ui.checkbox(&mut g.paint,tr(uk,"Малювати у сцені","Paint in scene"));ui.checkbox(&mut g.erase,tr(uk,"Гумка","Eraser"));ui.checkbox(&mut g.solid,tr(uk,"Колізія","Solid"));ui.add(egui::DragValue::new(&mut g.layer).prefix("Layer "));});ui.label(tr(uk,"Шлях PNG від кореня проєкту (порожній = білий тайл)","PNG path relative to project (empty = white tile)"));ui.text_edit_singleline(&mut g.asset);ui.checkbox(&mut g.auto,"4×4 autotile atlas");for (i,n) in ["Columns","Rows","Frame"].iter().enumerate(){ui.add(egui::DragValue::new(&mut g.atlas[i]).prefix(*n).range(0..=256));}ui.label(tr(uk,"ЛКМ / перетягування — малювання. Розмір = крок сітки. Ізометрія використовує координати сцени.","LMB / drag to paint. Size = grid step. Isometric mode uses world coordinates."));}
pub(super) fn paint(e:&mut Editor,pos:[f32;2]){let g=&e.gameplay;let grid=e.tools.snap.round().clamp(1.,512.) as u32;let cell=pos.map(|x|(x/grid as f32).round() as i32);if g.erase{forge_engine::erase_tile(&mut e.project,cell,grid,g.layer);}else{let sprite=if g.asset.is_empty(){None}else{if !g.asset.starts_with("assets/")||std::path::Path::new(&g.asset).components().any(|c|!matches!(c,std::path::Component::Normal(_))){e.status="Invalid tile asset path".into();return;}Some(g.asset.clone())};let id=forge_engine::paint_tile(&mut e.project,cell,grid,g.layer,sprite,g.solid);if let Some(o)=e.project.objects.iter_mut().find(|o|o.id==id){o.animation.columns=g.atlas[0].max(1);o.animation.rows=g.atlas[1].max(1);o.animation.start=g.atlas[2];o.animation.frames=1;}}if g.auto{forge_engine::autotile(&mut e.project,g.layer,grid);}}
pub(super) fn graph(ui:&mut egui::Ui,o:&mut Object,g:&mut GameplayUi){ui.horizontal_wrapped(|ui|{for n in [NodeKind::SetVariable,NodeKind::AddVariable,NodeKind::MultiplyVariable,NodeKind::IfPositive,NodeKind::Update,NodeKind::Trigger,NodeKind::IfRight,NodeKind::IfJump,NodeKind::MoveRight,NodeKind::MoveLeft,NodeKind::MoveUp,NodeKind::MoveDown,NodeKind::Jump]{if ui.small_button(format!("+ {n:?}")).clicked()&&o.graph.nodes.len()<128{o.graph.nodes.push(n);}}if ui.button("Clear").clicked(){o.graph=Default::default();g.positions.retain(|(id,_),_|*id!=o.id);g.link=None;}});ui.collapsing("Variables / parameters",|ui|{for (i,n) in o.graph.nodes.iter().enumerate(){if matches!(n,NodeKind::SetVariable|NodeKind::AddVariable|NodeKind::MultiplyVariable|NodeKind::IfPositive){let p=o.graph.params.entry(i).or_default();ui.horizontal(|ui|{ui.label(format!("{i}: {n:?}"));ui.text_edit_singleline(&mut p.variable);ui.add(egui::DragValue::new(&mut p.value));});}}});ui.label("Click OUT then IN to toggle link · drag node header · conditions gate outgoing edges");let size=egui::vec2(ui.available_width().max(300.),(ui.available_height()-5.).max(150.));let (rect,_)=ui.allocate_exact_size(size,egui::Sense::hover());let painter=ui.painter_at(rect);painter.rect_filled(rect,4.,egui::Color32::from_gray(20));let mut rects=vec![];for i in 0..o.graph.nodes.len(){let p=g.positions.entry((o.id,i)).or_insert_with(||o.pro.graph_positions.get(i).map(|p|egui::vec2(p[0],p[1])).unwrap_or_else(||egui::vec2(12.+(i%4) as f32*145.,12.+(i/4) as f32*70.)));let r=egui::Rect::from_min_size(rect.min+*p,egui::vec2(130.,52.));rects.push(r);}for [a,b] in &o.graph.edges{if let (Some(a),Some(b))=(rects.get(*a),rects.get(*b)){painter.line_segment([a.right_center()+egui::vec2(0.,12.),b.left_center()+egui::vec2(0.,12.)],egui::Stroke::new(2_f32,egui::Color32::LIGHT_BLUE));}}for (i,r) in rects.into_iter().enumerate(){let header=egui::Rect::from_min_max(r.min,egui::pos2(r.right(),r.top()+25.));let response=ui.interact(header,ui.id().with((o.id,i,"drag")),egui::Sense::drag());if response.dragged(){if let Some(p)=g.positions.get_mut(&(o.id,i)){*p+=ui.input(|i|i.pointer.delta());o.pro.graph_positions.resize(o.graph.nodes.len(),[12.,12.]);o.pro.graph_positions[i]=[p.x,p.y];}}painter.rect_filled(r,4.,egui::Color32::from_gray(50));painter.text(header.center(),egui::Align2::CENTER_CENTER,format!("{:?}",o.graph.nodes[i]),egui::FontId::proportional(12.),egui::Color32::WHITE);for (out,p) in [(false,r.left_center()),(true,r.right_center())]{let p=p+egui::vec2(0.,12.);let hit=ui.interact(egui::Rect::from_center_size(p,egui::vec2(22.,22.)),ui.id().with((o.id,i,out)),egui::Sense::click());painter.circle_filled(p,6.,if out&&g.link==Some(i){egui::Color32::YELLOW}else{egui::Color32::LIGHT_BLUE});if hit.clicked(){if out{g.link=Some(i);}else if let Some(a)=g.link.take(){if a!=i&&a<o.graph.nodes.len(){let edge=[a,i];if o.graph.edges.contains(&edge){o.graph.edges.retain(|e|*e!=edge);}else{o.graph.edges.push(edge);}}}}}}}
pub(super) fn components(ui:&mut egui::Ui,o:&mut Object){use forge_engine::*;ui.collapsing("Inventory pickup / Предмет",|ui|{let mut enabled=o.pro.pickup.is_some();if ui.checkbox(&mut enabled,"Collectible (E)").changed(){o.pro.pickup=enabled.then(ItemStack::default);}if let Some(item)=&mut o.pro.pickup{ui.text_edit_singleline(&mut item.item);ui.add(egui::DragValue::new(&mut item.count).range(1..=99).prefix("Count "));if !item.valid(){ui.colored_label(egui::Color32::LIGHT_RED,"Invalid item name or quantity");}}});ui.collapsing("Combat / Бій",|ui|{let mut enabled=o.pro.combat.is_some();if ui.checkbox(&mut enabled,"Combat component").changed(){o.pro.combat=enabled.then(Default::default);}if let Some(c)=&mut o.pro.combat{ui.add(egui::DragValue::new(&mut c.team).prefix("Team "));ui.add(egui::DragValue::new(&mut c.max_health).range(1. ..=10000.).prefix("Max HP "));ui.add(egui::DragValue::new(&mut c.health).range(0. ..=c.max_health.max(1.)).prefix("HP "));ui.add(egui::DragValue::new(&mut c.damage).range(0. ..=10000.).prefix("Damage "));for v in &mut c.reach{ui.add(egui::DragValue::new(v).range(0. ..=1000.).prefix("Hitbox "));}ui.add(egui::DragValue::new(&mut c.knockback).range(0. ..=1000.).prefix("Knockback "));ui.add(egui::DragValue::new(&mut c.cooldown).range(0.01 ..=10.).prefix("Cooldown "));}});ui.collapsing("Rapier collider",|ui|{let p=&mut o.pro.physics;egui::ComboBox::from_id_salt("shape").selected_text(format!("{:?}",p.shape)).show_ui(ui,|ui|{for s in [Shape::Box,Shape::Circle,Shape::Capsule]{ui.selectable_value(&mut p.shape,s,format!("{s:?}"));}});ui.add(egui::DragValue::new(&mut p.mass).range(0.001..=1000.).prefix("Mass "));ui.add(egui::Slider::new(&mut p.friction,0. ..=2.).text("Friction"));ui.checkbox(&mut p.lock_rotation,"Lock rotation");});ui.collapsing("Light",|ui|{if ui.button("Add / remove light").clicked(){o.pro.light=if o.pro.light.is_some(){None}else{Some(Light::default())};}if let Some(l)=&mut o.pro.light{ui.add(egui::DragValue::new(&mut l.radius).range(1. ..=4000.).prefix("Radius "));ui.add(egui::Slider::new(&mut l.intensity,0. ..=4.).text("Intensity"));ui.color_edit_button_rgb(&mut l.color);}});ui.collapsing("Particles",|ui|{ui.horizontal_wrapped(|ui|{for effect in [Effect::Fire,Effect::Smoke,Effect::Rain,Effect::Snow,Effect::Sparks,Effect::Custom]{if ui.button(format!("{effect:?}")).clicked(){o.pro.emitter=Some(Emitter::preset(effect));}}if ui.button("Remove").clicked(){o.pro.emitter=None;}});if let Some(p)=&mut o.pro.emitter{ui.add(egui::Slider::new(&mut p.rate,1. ..=200.).text("Rate"));ui.add(egui::Slider::new(&mut p.lifetime,0.05..=10.).text("Lifetime"));ui.add(egui::DragValue::new(&mut p.size).range(1. ..=64.).prefix("Size "));ui.add(egui::Slider::new(&mut p.spread,0. ..=128.).text("GPU spawn spread"));ui.label(format!("Baseline GPU slots: {} / 128",forge_engine::gpu_particles::count(p)));for v in &mut p.velocity{ui.add(egui::DragValue::new(v));}ui.color_edit_button_srgba_unmultiplied(&mut p.color);}});ui.collapsing("Audio",|ui|{if ui.button("Add / remove audio").clicked(){o.pro.sound=if o.pro.sound.is_some(){None}else{Some(Sound::default())};}if let Some(s)=&mut o.pro.sound{ui.text_edit_singleline(&mut s.path);ui.checkbox(&mut s.music,"Music bus");ui.checkbox(&mut s.looping,"Loop");ui.checkbox(&mut s.spatial,"Distance attenuation (SFX)");ui.checkbox(&mut s.stereo_pan,"Stereo positioning in Player (SFX)");if s.spatial{ui.add(egui::DragValue::new(&mut s.distance).range(1. ..=10000.).prefix("Range "));}ui.add(egui::Slider::new(&mut s.volume,0. ..=1.).text("Volume"));ui.add(egui::Slider::new(&mut s.speed,0.5 ..=2.).text("Playback speed / pitch"));let mut enabled=s.effects.is_some();if ui.checkbox(&mut enabled,"Streaming DSP (Player, PCM16 WAV)").changed(){s.effects=enabled.then(WavEffects::default);}if let Some(fx)=&mut s.effects{ui.add(egui::Slider::new(&mut fx.low_db,-12. ..=12.).text("Low EQ dB"));ui.add(egui::Slider::new(&mut fx.high_db,-12. ..=12.).text("High EQ dB"));ui.add(egui::Slider::new(&mut fx.room,0. ..=1.).text("Room feedback"));ui.small("Applied at next scene start. Unsupported WAV or budget exceeded: normal playback.");}}});}
pub(super) fn settings(ui:&mut egui::Ui,e:&mut Editor){let s=&mut e.project.settings;inventory_settings(ui,s);item_catalog(ui,s);ui.checkbox(&mut s.gpu_lighting,"GPU lighting (2D)");ui.checkbox(&mut s.gpu_particles,"GPU particles (2D, experimental)");ui.checkbox(&mut s.gpu_particle_quads,"GPU vertex quads (experimental fast path)");ui.add(egui::Slider::new(&mut s.gpu_particle_limit,1..=256).text("GPU slots per small emitter"));ui.label("Large emitters remain capped at 128; higher budgets may lower FPS.");ui.add(egui::Slider::new(&mut s.gpu_light_count,1..=3).text("Lights per sprite"));ui.add(egui::Slider::new(&mut s.shadow_softness,0. ..=32.).text("Shadow softness (px)"));ui.label("GPU particle budget: 8 emitters; 128–256 slots each, remaining emitters use CPU.");ui.checkbox(&mut s.rapier,"Rapier physics (experimental)");ui.add(egui::Slider::new(&mut s.ambient,0. ..=1.).text("Ambient"));for (name,v) in [("Master",&mut s.master),("Music",&mut s.music),("SFX",&mut s.sfx)]{ui.add(egui::Slider::new(v,0. ..=1.).text(name));}if ui.button("Add HUD button").clicked(){s.widgets.push(forge_engine::Widget::default());}if ui.button("Add inventory layout").clicked(){for i in 0..6{s.widgets.push(forge_engine::Widget{text:format!("Slot {}",i+1),action:"label".into(),group:"HUD/Inventory".into(),anchor:[0.05,0.15],..Default::default()});}}if ui.button("Add control menu").clicked(){for (text,action) in [("Left","left"),("Right","right"),("Jump","jump")]{s.widgets.push(forge_engine::Widget{text:text.into(),action:action.into(),group:"Controls".into(),anchor:[0.05,0.7],..Default::default()});}}let mut duplicate=None;let mut remove=None;for (i,w) in s.widgets.iter_mut().enumerate(){ui.push_id(i,|ui|{ui.text_edit_singleline(&mut w.text);ui.add(egui::TextEdit::singleline(&mut w.group).hint_text("Container path, e.g. HUD/Inventory"));egui::ComboBox::from_id_salt("action").selected_text(&w.action).show_ui(ui,|ui|{for a in ["left","right","jump","label"]{ui.selectable_value(&mut w.action,a.into(),a);}});for (axis,v) in w.size.iter_mut().enumerate(){ui.add(egui::DragValue::new(v).range(16. ..=800.).prefix(if axis==0{"Width "}else{"Height "}));}for v in &mut w.anchor{ui.add(egui::Slider::new(v,0. ..=1.));}if ui.button("Duplicate widget").clicked(){duplicate=Some(w.clone());}if ui.button("Remove").clicked(){remove=Some(i);}});}if let Some(i)=remove{s.widgets.remove(i);}if let Some(w)=duplicate{s.widgets.push(w);}ui.collapsing("HUD layout / Макет HUD",|ui|{let (rect,_)=ui.allocate_exact_size(egui::vec2(ui.available_width().max(120.),150.),egui::Sense::hover());let painter=ui.painter_at(rect);painter.rect_filled(rect,3.,egui::Color32::from_gray(22));let resolution=s.production.resolution;for (i,w) in s.widgets.iter_mut().enumerate(){let pos=rect.min+egui::vec2(w.anchor[0]*rect.width(),w.anchor[1]*rect.height());let size=egui::vec2((w.size[0]/resolution[0].max(1) as f32*rect.width()).max(12.),(w.size[1]/resolution[1].max(1) as f32*rect.height()).max(12.));let r=egui::Rect::from_min_size(pos,size);let response=ui.interact(r,ui.id().with(("hud_layout",i)),egui::Sense::drag());if response.dragged(){let delta=ui.input(|x|x.pointer.delta());w.anchor[0]=(w.anchor[0]+delta.x/rect.width()).clamp(0.,1.);w.anchor[1]=(w.anchor[1]+delta.y/rect.height()).clamp(0.,1.);}painter.rect_filled(r,2.,egui::Color32::from_rgb(60,90,125));painter.text(r.center(),egui::Align2::CENTER_CENTER,&w.text,egui::FontId::proportional(10.),egui::Color32::WHITE);}});if ui.button("Export Windows project bundle").clicked(){if let Some(path)=&e.path{if let Some(dest)=rfd::FileDialog::new().pick_folder(){e.status=match forge_engine::export_bundle(path,&dest){Ok(())=>"Bundle exported; copy ForgePlayer.exe here".into(),Err(e)=>e};}}}}

pub(super) fn production_object(ui:&mut egui::Ui,o:&mut Object){ui.collapsing("Production / Виробництво",|ui|{let mut nav=o.production.navigation.is_some();if ui.checkbox(&mut nav,"Navigation / Навігація").changed(){o.production.navigation=nav.then(Default::default);}if let Some(n)=&mut o.production.navigation{ui.checkbox(&mut n.enabled,"Enabled");for i in 0..2{ui.add(egui::DragValue::new(&mut n.target[i]).prefix(["Target X ","Target Y "][i]));}ui.add(egui::DragValue::new(&mut n.speed).range(0. ..=2000.).prefix("Speed "));ui.add(egui::DragValue::new(&mut n.grid).range(8..=256).prefix("Grid "));ui.label("Body=None; non-player NPC");}let mut tex=o.production.particle_texture.clone().unwrap_or_default();ui.label("Particle texture (assets/…)");if ui.text_edit_singleline(&mut tex).changed(){o.production.particle_texture=(!tex.is_empty()).then_some(tex);} });}
pub(super) fn production_settings(ui:&mut egui::Ui,e:&mut Editor){let chunks=forge_engine::tile_chunks(&e.project).len();ui.label(format!("Tile chunks (16×16): {chunks}"));let s=&mut e.project.settings.production;ui.collapsing("Input / Керування",|ui|{for (name,key) in [("Left",&mut s.controls.left),("Right",&mut s.controls.right),("Up",&mut s.controls.up),("Down",&mut s.controls.down)]{ui.horizontal(|ui|{ui.label(name);egui::ComboBox::from_id_salt(name).selected_text(key.as_str()).show_ui(ui,|ui|{for k in ["A","D","W","S","Left","Right","Up","Down","Space","J","L","I","K"]{ui.selectable_value(key,k.into(),k);}});});}ui.add(egui::Slider::new(&mut s.controls.deadzone,0. ..=0.9).text("Gamepad deadzone"));});ui.collapsing("Build profile / Збірка",|ui|{ui.text_edit_singleline(&mut s.package_id);for i in 0..2{ui.add(egui::DragValue::new(&mut s.resolution[i]).range(320..=3840).prefix(["Width ","Height "][i]));}});ui.collapsing("Rope joints / З'єднання",|ui|{let bodies=e.project.objects.iter().filter(|o|o.body!=Body::None&&!o.camera).map(|o|(o.id,o.name.clone())).collect::<Vec<_>>();if bodies.len()>=2&&ui.button("Add rope joint").clicked(){s.joints.push(forge_engine::DistanceJoint{a:bodies[0].0,b:bodies[1].0,length:100.});}let mut remove=None;for (i,j) in s.joints.iter_mut().enumerate(){ui.push_id(i,|ui|{for (label,id) in [("A",&mut j.a),("B",&mut j.b)]{egui::ComboBox::from_id_salt(label).selected_text(bodies.iter().find(|(x,_)|x==id).map(|(_,n)|n.as_str()).unwrap_or("Missing")).show_ui(ui,|ui|{for (x,n) in &bodies{ui.selectable_value(id,*x,n);}});}ui.add(egui::DragValue::new(&mut j.length).range(1. ..=10000.).prefix("Max length "));if ui.button("Remove").clicked(){remove=Some(i);}});}if let Some(i)=remove{s.joints.remove(i);}});}

fn inventory_settings(ui:&mut egui::Ui,s:&mut forge_engine::GameSettings){ui.collapsing("Inventory Engine / Інвентар",|ui|{let mut enabled=s.inventory.is_some();if ui.checkbox(&mut enabled,"Enable inventory in Player").changed(){s.inventory=enabled.then(forge_engine::Inventory::default);}if let Some(inv)=&mut s.inventory{let mut n=inv.slots.len();if ui.add(egui::DragValue::new(&mut n).range(1..=64).prefix("Slots ")).changed(){if n>=inv.slots.len()||inv.slots[n..].iter().all(Option::is_none){inv.slots.resize(n,None);}}for (i,slot) in inv.slots.iter_mut().enumerate(){ui.push_id(i,|ui|{ui.horizontal_wrapped(|ui|{ui.label(format!("{}",i+1));if let Some(item)=slot{ui.text_edit_singleline(&mut item.item);ui.add(egui::DragValue::new(&mut item.count).range(1..=99));if ui.small_button("Clear").clicked(){*slot=None;}}else if ui.small_button("+ Item").clicked(){*slot=Some(forge_engine::ItemStack::default());}});});}if !inv.valid(){ui.colored_label(egui::Color32::LIGHT_RED,"Inventory has invalid items");}ui.small("I opens inventory in Player; E collects a nearby leaf pickup. Save/load is explicit.");}});}

fn item_catalog(ui:&mut egui::Ui,s:&mut forge_engine::GameSettings){ui.collapsing("Item catalog / Каталог предметів",|ui|{let id=ui.id().with("new_item_name23");let mut name=ui.ctx().data(|d|d.get_temp::<String>(id)).unwrap_or_default();ui.horizontal(|ui|{ui.text_edit_singleline(&mut name);if ui.button("Add definition").clicked()&&!name.trim().is_empty()&&name.len()<=128&&s.item_catalog.len()<512{s.item_catalog.entry(name.trim().to_string()).or_default();name.clear();}});ui.ctx().data_mut(|d|d.insert_temp(id,name));let mut remove=None;for (name,item) in &mut s.item_catalog{ui.push_id(name,|ui|{ui.collapsing(name.as_str(),|ui|{egui::ComboBox::from_id_salt("equip").selected_text(if item.equip_slot.is_empty(){"Not equipment"}else{item.equip_slot.as_str()}).show_ui(ui,|ui|{for slot in ["","weapon","armor","accessory","head","offhand"]{ui.selectable_value(&mut item.equip_slot,slot.into(),if slot.is_empty(){"Not equipment"}else{slot});}});ui.add(egui::DragValue::new(&mut item.heal).range(0. ..=1000.).prefix("Heal "));ui.add(egui::DragValue::new(&mut item.damage_bonus).range(0. ..=1000.).prefix("Damage bonus "));ui.label("Variable effect (optional)");ui.text_edit_singleline(&mut item.variable);ui.add(egui::DragValue::new(&mut item.variable_delta).range(-10000. ..=10000.).prefix("Delta "));if !item.valid(){ui.colored_label(egui::Color32::LIGHT_RED,"Invalid definition");}if ui.button("Remove definition").clicked(){remove=Some(name.clone());}});});}if let Some(n)=remove{s.item_catalog.remove(&n);}ui.small("Names match inventory/pickup names exactly. Heal and damage use Combat; variable effects work on ordinary projects.");});}
